const IMGS = {
  bg_default: "data:image/jpeg;base64,",
  bg_jewel: "data:image/jpeg;base64,",
  bg_bitter: "data:image/jpeg;base64,",
  card1_thumb: "data:image/jpeg;base64,",
  card2_thumb: "data:image/jpeg;base64,",
};

/* ─────────────────────────────────────────
   app.js  —  Mono // Lab  3D Renders page
   Depends on: imgdata.js (base64 image URIs)
───────────────────────────────────────── */
(function () {
  'use strict';

  /* ── Apply background images ── */
  document.getElementById('bgD').style.backgroundImage   = 'url(' + IMGS.bg_default + ')';
  document.getElementById('bgJ').style.backgroundImage   = 'url(' + IMGS.bg_jewel   + ')';
  document.getElementById('bgB').style.backgroundImage   = 'url(' + IMGS.bg_bitter  + ')';
  document.getElementById('c1img').style.backgroundImage = 'url(' + IMGS.card1_thumb + ')';
  document.getElementById('c2img').style.backgroundImage = 'url(' + IMGS.card2_thumb + ')';

  /* ── DOM refs ── */
  var bgD  = document.getElementById('bgD'),
      bgJ  = document.getElementById('bgJ'),
      bgB  = document.getElementById('bgB'),
      c1   = document.getElementById('c1'),
      c2   = document.getElementById('c2'),
      navs = document.querySelectorAll('.nav-item'),
      back = document.getElementById('backBtn');

  /* ── BG state ── */
  function setBg(state) {
    bgD.style.opacity = state === 'default' ? '1' : '0';
    bgJ.style.opacity = state === 'jewel'   ? '1' : '0';
    bgB.style.opacity = state === 'bitter'  ? '1' : '0';
  }

  /* ── Card hover ── */
  c1.addEventListener('mouseenter', function () { c1.classList.add('hov');    setBg('jewel');   });
  c1.addEventListener('mouseleave', function () { c1.classList.remove('hov'); setBg('default'); });
  c2.addEventListener('mouseenter', function () { c2.classList.add('hov');    setBg('bitter');  });
  c2.addEventListener('mouseleave', function () { c2.classList.remove('hov'); setBg('default'); });

  /* Keyboard support */
  [c1, c2].forEach(function (card) {
    card.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        card.classList.toggle('hov');
      }
    });
  });

  /* ── Nav ── */
  navs.forEach(function (n) {
    n.addEventListener('click', function (e) {
      e.preventDefault();
      navs.forEach(function (x) { x.classList.remove('active'); });
      n.classList.add('active');
      /* Route here in your real app: router.push(n.dataset.p) */
    });
  });

  /* ── Back button ── */
  back.addEventListener('click', function () {
    /* Replace with your router's back call */
    window.history.back();
  });

  /* ── Init ── */
  setBg('default');
}());
